<script setup>
import { ref, computed } from 'vue';
import OperatorPerusahaanLayout from '@/Layouts/OperatorPerusahaanLayout.vue';
import { Head, Link } from '@inertiajs/vue3';

defineOptions({ layout: OperatorPerusahaanLayout });

const tagihans = ref([
  { id: 1, kode: 'INV-202505-001', pelanggan: 'Pak Sugeng', paket: 'Silver 20Mbps', nominal: 250000, periode_dari: '2025-05-01', periode_sampai: '2025-05-31', tgl_jatuh_tempo: '2025-05-10', status: 'Lunas', created_at: '2025-04-25' },
  { id: 2, kode: 'INV-202505-002', pelanggan: 'Bu Rini', paket: 'Gold 50Mbps', nominal: 400000, periode_dari: '2025-05-01', periode_sampai: '2025-05-31', tgl_jatuh_tempo: '2025-05-10', status: 'Belum Bayar', created_at: '2025-04-25' },
  { id: 3, kode: 'INV-202504-001', pelanggan: 'Pak Herman', paket: 'Basic 10Mbps', nominal: 150000, periode_dari: '2025-04-01', periode_sampai: '2025-04-30', tgl_jatuh_tempo: '2025-04-10', status: 'Kadaluarsa', created_at: '2025-03-25' },
  { id: 4, kode: 'INV-202505-003', pelanggan: 'Mbak Dewi', paket: 'Platinum 100Mbps', nominal: 750000, periode_dari: '2025-05-01', periode_sampai: '2025-05-31', tgl_jatuh_tempo: '2025-05-10', status: 'Lunas', created_at: '2025-04-25' },
  { id: 5, kode: 'INV-202505-004', pelanggan: 'Pak Slamet', paket: 'Basic 10Mbps', nominal: 150000, periode_dari: '2025-05-01', periode_sampai: '2025-05-31', tgl_jatuh_tempo: '2025-05-10', status: 'Belum Bayar', created_at: '2025-04-25' },
]);

const searchInput = ref(''); const search = ref(''); const statusFilter = ref(''); const bulanFilter = ref(''); const tahunFilter = ref(''); const currentPage = ref(1); const perPage = ref(5); const perPageOptions = [5, 10, 25, 50, 100];
const selectedIds = ref([]); const selectAll = ref(false); const sortFields = ref([]); const selectedItem = ref(null);
const showCreateModal = ref(false); const showDetailModal = ref(false); const showEditModal = ref(false); const showDeleteModal = ref(false);
const form = ref({ id: null, kode: '', pelanggan: '', paket: '', nominal: '', periode_dari: '', periode_sampai: '', tgl_jatuh_tempo: '', status: 'Belum Bayar' });
const formErrors = ref({}); const nextId = ref(6);
let autoNum = 5;

function applySearch() { search.value = searchInput.value; currentPage.value = 1; }
function clearSearch() { searchInput.value = ''; search.value = ''; currentPage.value = 1; }
function applyStatusFilter(s) { statusFilter.value = s; currentPage.value = 1; }
function applyBulanFilter(b) { bulanFilter.value = b; currentPage.value = 1; }
function applyTahunFilter(t) { tahunFilter.value = t; currentPage.value = 1; }
function changePerPage(n) { perPage.value = n; currentPage.value = 1; }
function toggleSelectAll() { selectedIds.value = selectAll.value ? paginatedTagihans.value.map(t => t.id) : []; }
function toggleSelect(id) { const i = selectedIds.value.indexOf(id); i === -1 ? selectedIds.value.push(id) : selectedIds.value.splice(i, 1); selectAll.value = selectedIds.value.length === paginatedTagihans.value.length; }
function bulkDelete() { tagihans.value = tagihans.value.filter(t => !selectedIds.value.includes(t.id)); selectedIds.value = []; selectAll.value = false; }
function sort(field) { const e = sortFields.value.findIndex(s => s.field === field); if (e !== -1) { if (sortFields.value[e].dir === 'asc') sortFields.value[e].dir = 'desc'; else sortFields.value.splice(e, 1); } else sortFields.value.push({ field, dir: 'asc' }); }
function sortIcon(f) { const s = sortFields.value.find(s => s.field === f); if (!s) return 'fa-sort'; return s.dir === 'asc' ? 'fa-sort-up' : 'fa-sort-down'; }
function sortOrder(f) { const i = sortFields.value.findIndex(s => s.field === f); return i !== -1 ? i + 1 : null; }
function statusBadge(s) { if (s === 'Lunas') return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400'; if (s === 'Belum Bayar') return 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400'; return 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'; }
function formatRupiah(n) { return 'Rp ' + Number(n).toLocaleString('id-ID'); }

const filteredTagihans = computed(() => {
  let r = [...tagihans.value];
  if (search.value) { const q = search.value.toLowerCase(); r = r.filter(x => x.kode.toLowerCase().includes(q) || x.pelanggan.toLowerCase().includes(q) || x.paket.toLowerCase().includes(q)); }
  if (statusFilter.value) r = r.filter(x => x.status === statusFilter.value);
  if (bulanFilter.value) r = r.filter(x => x.periode_dari && Number(x.periode_dari.split('-')[1]) === Number(bulanFilter.value));
  if (tahunFilter.value) r = r.filter(x => x.periode_dari && x.periode_dari.split('-')[0] === tahunFilter.value);
  if (sortFields.value.length > 0) r.sort((a, b) => { for (const s of sortFields.value) { let av = a[s.field], bv = b[s.field]; if (s.field === 'nominal') { av = Number(av); bv = Number(bv); } if (av != bv) return (typeof av === 'string' ? av.localeCompare(bv) : av - bv) * (s.dir === 'asc' ? 1 : -1); } return 0; });
  return r;
});
const totalPages = computed(() => Math.ceil(filteredTagihans.value.length / perPage.value) || 1);
const paginatedTagihans = computed(() => { const s = (currentPage.value - 1) * perPage.value; return filteredTagihans.value.slice(s, s + perPage.value); });
const visiblePages = computed(() => { const p = []; const t = totalPages.value; const c = currentPage.value; let st = Math.max(1, c - 2); let en = Math.min(t, c + 2); if (en - st < 4) { if (st === 1) en = Math.min(t, st + 4); else st = Math.max(1, en - 4); } for (let i = st; i <= en; i++) p.push(i); return p; });

function openCreate() { const now = new Date(); const month = String(now.getMonth() + 1).padStart(2, '0'); const year = now.getFullYear(); autoNum++; const kode = `INV-${year}${month}-${String(autoNum).padStart(3, '0')}`; form.value = { id: null, kode, pelanggan: '', paket: '', nominal: '', periode_dari: '', periode_sampai: '', tgl_jatuh_tempo: '', status: 'Belum Bayar' }; formErrors.value = {}; showCreateModal.value = true; }
function openDetail(t) { selectedItem.value = t; showDetailModal.value = true; }
function openEdit(t) { form.value = { ...t }; formErrors.value = {}; showEditModal.value = true; }
function openDelete(t) { selectedItem.value = t; showDeleteModal.value = true; }
function validateForm() { const e = {}; if (!form.value.kode.trim()) e.kode = 'Kode wajib diisi'; if (!form.value.pelanggan.trim()) e.pelanggan = 'Pelanggan wajib diisi'; if (!form.value.paket.trim()) e.paket = 'Paket wajib diisi'; if (!form.value.nominal || Number(form.value.nominal) <= 0) e.nominal = 'Nominal tidak valid'; if (!form.value.periode_dari) e.periode_dari = 'Periode dari wajib diisi'; if (!form.value.periode_sampai) e.periode_sampai = 'Periode sampai wajib diisi'; if (!form.value.tgl_jatuh_tempo) e.tgl_jatuh_tempo = 'Tanggal jatuh tempo wajib diisi'; formErrors.value = e; return Object.keys(e).length === 0; }
function saveCreate() { if (!validateForm()) return; tagihans.value.unshift({ id: nextId.value++, ...form.value, nominal: Number(form.value.nominal), created_at: new Date().toISOString().split('T')[0] }); showCreateModal.value = false; }
function saveEdit() { if (!validateForm()) return; const i = tagihans.value.findIndex(t => t.id === form.value.id); if (i !== -1) tagihans.value[i] = { ...tagihans.value[i], ...form.value, nominal: Number(form.value.nominal) }; showEditModal.value = false; }
function confirmDelete() { tagihans.value = tagihans.value.filter(t => t.id !== selectedItem.value.id); showDeleteModal.value = false; if (paginatedTagihans.value.length === 0 && currentPage.value > 1) currentPage.value--; }
function goToPage(p) { currentPage.value = Math.max(1, Math.min(p, totalPages.value)); }
</script>

<template>
  <div>
    <Head title="Tagihan | Perusahaan" />
    <div class="space-y-6">
      <nav class="flex items-center gap-1.5 text-sm"><Link href="/operator-perusahaan/dashboard" class="text-gray-500 dark:text-gray-400 hover:text-sky-600 dark:hover:text-sky-400 transition-colors"><i class="fas fa-home"></i></Link><i class="fas fa-chevron-right text-[10px] text-gray-400 dark:text-gray-500"></i><Link href="/operator-perusahaan/dashboard" class="text-gray-500 dark:text-gray-400 hover:text-sky-600 dark:hover:text-sky-400 transition-colors">Dashboard</Link><i class="fas fa-chevron-right text-[10px] text-gray-400 dark:text-gray-500"></i><span class="text-gray-900 dark:text-white font-medium">Tagihan</span></nav>
      <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3"><div><h2 class="text-2xl font-bold text-gray-900 dark:text-white">Tagihan</h2><p class="text-sm text-gray-500 dark:text-gray-400 mt-0.5">Kelola tagihan bulanan pelanggan.</p></div><button @click="openCreate" class="inline-flex items-center px-4 py-2.5 bg-sky-600 text-white text-sm font-medium rounded-lg hover:bg-sky-700 transition-colors shadow-sm"><i class="fas fa-plus mr-1.5"></i> Tambah Tagihan</button></div>
      <div class="flex flex-row flex-wrap items-center gap-3"><div class="relative w-full sm:w-56"><div class="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none"><i class="fas fa-search text-gray-400 text-sm"></i></div><input v-model="searchInput" type="text" placeholder="Cari kode/pelanggan..." class="w-full pl-10 pr-9 py-2.5 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white text-sm focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none transition-colors" @keydown.enter="applySearch" /><div class="absolute inset-y-0 right-0 flex items-center pr-1.5"><button v-if="searchInput" @click="clearSearch" class="p-1.5 rounded text-gray-400 hover:text-gray-600 dark:hover:text-white transition-colors" title="Clear"><i class="fas fa-times text-xs"></i></button></div></div><select :value="bulanFilter" @change="applyBulanFilter($event.target.value)" class="px-3 py-2.5 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white text-sm focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none transition-colors"><option value="">Bulan</option><option value="1">Jan</option><option value="2">Feb</option><option value="3">Mar</option><option value="4">Apr</option><option value="5">Mei</option><option value="6">Jun</option><option value="7">Jul</option><option value="8">Agu</option><option value="9">Sep</option><option value="10">Okt</option><option value="11">Nov</option><option value="12">Des</option></select><select :value="tahunFilter" @change="applyTahunFilter($event.target.value)" class="px-3 py-2.5 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white text-sm focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none transition-colors"><option value="">Tahun</option><option value="2024">2024</option><option value="2025">2025</option><option value="2026">2026</option></select><div class="flex gap-1 flex-wrap"><button v-for="s in [{v:'',l:'Semua'},{v:'Lunas',l:'Lunas'},{v:'Belum Bayar',l:'Belum'},{v:'Kadaluarsa',l:'Kadaluarsa'}]" :key="s.v" @click="applyStatusFilter(s.v)" :class="['px-3 py-2 rounded-lg text-xs font-medium border transition-colors whitespace-nowrap', statusFilter === s.v ? (s.v === 'Lunas' ? 'bg-emerald-50 dark:bg-emerald-900/30 border-emerald-300 dark:border-emerald-700 text-emerald-700 dark:text-emerald-400' : s.v === 'Belum Bayar' ? 'bg-amber-50 dark:bg-amber-900/30 border-amber-300 dark:border-amber-700 text-amber-700 dark:text-amber-400' : s.v === 'Kadaluarsa' ? 'bg-red-50 dark:bg-red-900/30 border-red-300 dark:border-red-700 text-red-700 dark:text-red-400' : 'bg-sky-50 dark:bg-sky-900/30 border-sky-300 dark:border-sky-700 text-sky-700 dark:text-sky-400') : 'bg-white dark:bg-gray-800 border-gray-300 dark:border-gray-600 text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-700']"><i v-if="s.v === 'Lunas'" class="fas fa-check-circle mr-1"></i><i v-else-if="s.v === 'Belum Bayar'" class="fas fa-clock mr-1"></i><i v-else-if="s.v === 'Kadaluarsa'" class="fas fa-times-circle mr-1"></i>{{ s.l }}</button></div><span class="text-sm text-gray-500 dark:text-gray-400 whitespace-nowrap">{{ filteredTagihans.length }} data</span><button v-if="search || statusFilter || bulanFilter || tahunFilter" @click="searchInput = ''; search = ''; applyStatusFilter(''); bulanFilter = ''; tahunFilter = ''" class="text-xs text-red-500 hover:text-red-700 dark:hover:text-red-400 underline whitespace-nowrap">Reset filter</button></div>
      <div v-if="selectedIds.length > 0" class="flex items-center justify-between px-4 py-3 bg-sky-50 dark:bg-sky-900/20 border border-sky-200 dark:border-sky-800 rounded-xl shadow-sm"><span class="text-sm font-medium text-sky-700 dark:text-sky-300"><i class="fas fa-check-circle mr-1.5"></i> {{ selectedIds.length }} data dipilih</span><div class="flex items-center gap-2"><button @click="bulkDelete()" class="px-3 py-1.5 text-xs font-medium rounded-lg bg-red-600 text-white hover:bg-red-700 transition-colors"><i class="fas fa-trash-alt mr-1"></i> Hapus</button></div></div>
      <div class="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-sm min-w-[800px]"><thead class="bg-gray-50 dark:bg-gray-900 border-b border-gray-200 dark:border-gray-700"><tr><th class="px-4 py-3 w-10"><input v-model="selectAll" type="checkbox" @change="toggleSelectAll" class="rounded border-gray-300 dark:border-gray-600 text-sky-600 focus:ring-sky-500" /></th><th @click="sort('kode')" class="px-4 py-3 text-left font-semibold text-gray-600 dark:text-gray-400 cursor-pointer select-none hover:text-gray-900 dark:hover:text-white transition-colors"><span class="inline-flex items-center gap-1">Kode <span v-if="sortOrder('kode')" class="inline-flex items-center gap-0.5 text-sky-500 dark:text-sky-400"><i :class="['fas', sortIcon('kode'), 'text-[10px]']"></i><span class="text-[10px] font-bold leading-none">{{ sortOrder('kode') }}</span></span><i v-else class="fas fa-sort text-[10px] text-gray-400 dark:text-gray-500"></i></span></th><th @click="sort('pelanggan')" class="px-4 py-3 text-left font-semibold text-gray-600 dark:text-gray-400 cursor-pointer select-none hover:text-gray-900 dark:hover:text-white transition-colors"><span class="inline-flex items-center gap-1">Pelanggan <span v-if="sortOrder('pelanggan')" class="inline-flex items-center gap-0.5 text-sky-500 dark:text-sky-400"><i :class="['fas', sortIcon('pelanggan'), 'text-[10px]']"></i><span class="text-[10px] font-bold leading-none">{{ sortOrder('pelanggan') }}</span></span><i v-else class="fas fa-sort text-[10px] text-gray-400 dark:text-gray-500"></i></span></th><th class="px-4 py-3 text-left font-semibold text-gray-600 dark:text-gray-400">Paket</th><th class="px-4 py-3 text-left font-semibold text-gray-600 dark:text-gray-400">Periode</th><th @click="sort('nominal')" class="px-4 py-3 text-left font-semibold text-gray-600 dark:text-gray-400 cursor-pointer select-none hover:text-gray-900 dark:hover:text-white transition-colors"><span class="inline-flex items-center gap-1">Nominal <span v-if="sortOrder('nominal')" class="inline-flex items-center gap-0.5 text-sky-500 dark:text-sky-400"><i :class="['fas', sortIcon('nominal'), 'text-[10px]']"></i><span class="text-[10px] font-bold leading-none">{{ sortOrder('nominal') }}</span></span><i v-else class="fas fa-sort text-[10px] text-gray-400 dark:text-gray-500"></i></span></th><th @click="sort('status')" class="px-4 py-3 text-left font-semibold text-gray-600 dark:text-gray-400 cursor-pointer select-none hover:text-gray-900 dark:hover:text-white transition-colors"><span class="inline-flex items-center gap-1">Status <span v-if="sortOrder('status')" class="inline-flex items-center gap-0.5 text-sky-500 dark:text-sky-400"><i :class="['fas', sortIcon('status'), 'text-[10px]']"></i><span class="text-[10px] font-bold leading-none">{{ sortOrder('status') }}</span></span><i v-else class="fas fa-sort text-[10px] text-gray-400 dark:text-gray-500"></i></span></th><th class="px-4 py-3 text-right font-semibold text-gray-600 dark:text-gray-400 w-32">Aksi</th></tr></thead><tbody class="divide-y divide-gray-200 dark:divide-gray-700"><tr v-if="paginatedTagihans.length === 0"><td colspan="7" class="px-4 py-16 text-center text-gray-500 dark:text-gray-400"><i class="fas fa-file-invoice text-3xl mb-2 block opacity-40"></i>Tidak ada data tagihan.</td></tr><tr v-for="t in paginatedTagihans" :key="t.id" class="hover:bg-gray-50 dark:hover:bg-gray-700/30 transition-colors"><td class="px-4 py-3"><input :checked="selectedIds.includes(t.id)" type="checkbox" @change="toggleSelect(t.id)" class="rounded border-gray-300 dark:border-gray-600 text-sky-600 focus:ring-sky-500" /></td><td class="px-4 py-3"><code class="text-sm font-mono text-gray-900 dark:text-white bg-gray-100 dark:bg-gray-700 px-2 py-0.5 rounded">{{ t.kode }}</code></td><td class="px-4 py-3"><span class="font-medium text-gray-900 dark:text-white whitespace-nowrap">{{ t.pelanggan }}</span></td><td class="px-4 py-3 text-gray-600 dark:text-gray-400 whitespace-nowrap"><span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-sky-100 text-sky-700 dark:bg-sky-900/30 dark:text-sky-400"><i class="fas fa-wifi text-[10px]"></i> {{ t.paket }}</span></td><td class="px-4 py-3 text-gray-600 dark:text-gray-400 whitespace-nowrap text-xs">{{ t.periode_dari }} <i class="fas fa-arrow-right mx-0.5 text-[10px] text-gray-400"></i> {{ t.periode_sampai }}</td><td class="px-4 py-3 text-gray-900 dark:text-white whitespace-nowrap font-medium">{{ formatRupiah(t.nominal) }}</td><td class="px-4 py-3 whitespace-nowrap"><span :class="['inline-flex px-2.5 py-0.5 rounded-full text-xs font-medium', statusBadge(t.status)]">{{ t.status }}</span></td><td class="px-4 py-3 whitespace-nowrap"><div class="flex items-center justify-end gap-1"><button @click="openDetail(t)" class="p-2 rounded-lg text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700 hover:text-sky-600 dark:hover:text-sky-400 transition-colors" title="Detail"><i class="fas fa-eye text-sm"></i></button><button @click="openEdit(t)" class="p-2 rounded-lg text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700 hover:text-sky-600 dark:hover:text-sky-400 transition-colors" title="Edit"><i class="fas fa-edit text-sm"></i></button><button @click="openDelete(t)" class="p-2 rounded-lg text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700 hover:text-red-600 dark:hover:text-red-400 transition-colors" title="Hapus"><i class="fas fa-trash-alt text-sm"></i></button></div></td></tr></tbody></table></div><div class="px-4 py-3 border-t border-gray-200 dark:border-gray-700 flex flex-col sm:flex-row items-center justify-between gap-3"><div class="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-400"><span>Tampilkan</span><select :value="perPage" @change="changePerPage(Number($event.target.value))" class="min-w-[65px] px-2 py-1 rounded-lg border bord